import json,tiktoken
enc=tiktoken.get_encoding("o200k_base")
t=lambda o:len(enc.encode(json.dumps(o,separators=(',',':'))))
L=lambda f:json.load(open(f))
p=L('poke.json'); print('pokemon full',t(p),'trim(name,types,base stats)',t({'name':p['name'],'types':[x['type']['name'] for x in p['types']],'stats':{s['stat']['name']:s['base_stat'] for s in p['stats']}}))
i=L('gh_issues.json'); print('gh issues x5 full',t(i),'trim',t([{k:(x[k] if k!='user' else x['user']['login']) for k in('number','title','state','user','created_at')}|{'labels':[l['name'] for l in x['labels']]} for x in i]))
r=L('gh_pulls.json'); print('gh pulls x5 full',t(r),'trim',t([{'number':x['number'],'title':x['title'],'user':x['user']['login'],'draft':x['draft'],'created_at':x['created_at']} for x in r]))
f=L('nws_forecast.json'); ps=f['properties']['periods']; print('nws forecast periods',len(ps),'full',t(f),'trim',t([{k:x[k] for k in('name','temperature','temperatureUnit','shortForecast')} for x in ps]))
h=L('nws_hourly.json'); ps=h['properties']['periods']; print('nws hourly periods',len(ps),'full',t(h),'trim(next 12 h)',t([{k:x[k] for k in('startTime','temperature','shortForecast')} for x in ps[:12]]))
a=L('nws_alerts.json'); fs=a['features']; print('nws alerts',len(fs),'full',t(a),'trim',t([{k:x['properties'][k] for k in('event','severity','areaDesc','expires')} for x in fs]))
c=L('coingecko.json'); print('coingecko full',t(c),'trim',t({'name':c['name'],'usd':c['market_data']['current_price']['usd'],'chg24h':c['market_data']['price_change_percentage_24h']}))
s=L('sec.json'); rc=s['filings']['recent']; print('sec top keys',list(s)[:8],'recent arrays',len(rc),'n filings',len(rc['accessionNumber']),'full',t(s),'trim last10 10-K/Q', t([{k:rc[k][j] for k in('form','filingDate','accessionNumber')} for j in range(10)]))
hs=L('hn_search.json'); print('hn search full',t(hs),'trim',t([{k:x[k] for k in('title','url','points','num_comments','objectID')} for x in hs['hits']]))
tm=L('tvmaze.json'); print('tvmaze embed full',t(tm),'ep count',len(tm['_embedded']['episodes']))
sp=L('poke_species.json'); print('species',t(sp))
